{"file_path":"$PROJECT/code/packages/ui/src/authors.ts","content":"/**
 * Who wrote what, from the engine's git blame of events.ndjson (GET /api/sessions/:id/authors).
 * Shown only where the author changes, so a single-author project shows nothing at all.
 */
import type { Event, StructureNode } from "@yolo-twice/core";
import type { Author, AuthorRun } from "./api";

export const sameAuthors = (a: Author[] = [], b: Author[] = []) => a.map((x) => x.email_sha256).join() === b.map((x) => x.email_sha256).join();

/** Distinct authors over every session of the project. */
export function authorCount(sessions: { authors?: Author[] }[]): number {
  return new Set(sessions.flatMap((s) => (s.authors ?? []).map((a) => a.email_sha256))).size;
}

/** Position of every event in the session file: blame is per line, so file order is the order that counts. */
export function eventOrder(events: Map<string, Event> | undefined): Map<string, number> {
  const m = new Map<string, number>();
  let i = 0;
  for (const id of events?.keys() ?? []) m.set(id, i++);
  return m;
}

function contains(node: StructureNode, at: number, order: Map<string, number>): boolean {
  const a = order.get(node.span.first);
  const b = order.get(node.span.last);
  return a !== undefined && b !== undefined && a <= at && at <= b;
}

/** The author of the run a node starts in. */
export function authorAt(node: StructureNode, runs: AuthorRun[], order: Map<string, number>): Author | undefined {
  const at = order.get(node.span.first);
  if (at === undefined) return undefined;
  return runs.find((r) => (order.get(r.first) ?? Infinity) <= at && at <= (order.get(r.last) ?? -Infinity));
}

/**
 * Where someone takes over, below `root`: the outermost part that holds each change of author.
 * Reader and graph mark the same parts, so a split view shows the takeover in the same place.
 */
export function takeovers(root: StructureNode, runs: AuthorRun[], order: Map<string, number>): Map<string, Author> {
  const out = new Map<string, Author>();
  for (const run of runs.slice(1)) {
    const at = order.get(run.first);
    if (at === undefined) continue;
    let node = root;
    for (;;) {
      const child = node.children.find((c) => contains(c, at, order));
      if (!child) break;
      if (child !== root) {
        out.set(child.id, run);
        break;
      }
      node = child;
    }
  }
  return out;
}
"}

{"file_path":"$PROJECT/code/packages/ui/src/Avatar.tsx","content":"import { useState } from "react";
import type { Author } from "./api";

/** A face from Gravatar; initials on a colour of their own when there is none (or no network). */
export function Avatar({ author, size = 18 }: { author: Author; size?: number }) {
  const [failed, setFailed] = useState(false);
  const initials = author.name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]!.toUpperCase())
    .join("");
  const hue = parseInt(author.email_sha256.slice(0, 4), 16) % 360;
  return (
    <span className="avatar" style={{ width: size, height: size, fontSize: size * 0.45, background: `hsl(${hue} 45% 45%)` }} title={author.name} aria-label={author.name}>
      {failed ? initials : <img src={`https://gravatar.com/avatar/${author.email_sha256}?s=${size * 2}&d=404`} alt="" width={size} height={size} onError={() => setFailed(true)} />}
    </span>
  );
}

/** One or more faces, overlapping a little. */
export function Avatars({ authors, size }: { authors: Author[]; size?: number }) {
  return (
    <span className="avatars">
      {authors.map((a) => (
        <Avatar key={a.email_sha256} author={a} size={size} />
      ))}
    </span>
  );
}
