{"file_path":"$PROJECT/code/packages/engine/src/forks.ts","content":"import fs from "node:fs";
import type { Event, Store } from "@yolo-twice/core";

/**
 * Sessions continued with `resume`: the rebuilt transcript keeps the original record ids, and its
 * title says "(resumed via yolo-twice)". So a fork is found from the events alone, nothing stored:
 * a session with that title whose first conversation event also lives in another session.
 */
export interface Fork {
  /** The session it was forked from. */
  from: string;
  /** Its events copied from there. */
  shared: Set<string>;
}

export const RESUMED = /\(resumed via yolo-twice\)\s*$/;

const isResumed = (events: Event[]) => RESUMED.test(events.find((e) => e.kind === "title")?.text ?? "");

export function findForks(sessions: Map<string, Event[]>): Map<string, Fork> {
  const out = new Map<string, Fork>();
  const ids = new Map([...sessions].map(([s, evs]) => [s, new Set(evs.map((e) => e.id))]));
  for (const [s, evs] of sessions) {
    if (!isResumed(evs)) continue;
    const first = evs.find((e) => e.kind !== "title")?.id;
    if (!first) continue;
    // the original over another fork of it; a fork of a fork when that is all there is
    const holders = [...sessions.keys()].filter((o) => o !== s && ids.get(o)!.has(first));
    const from = holders.find((o) => !isResumed(sessions.get(o)!)) ?? holders[0];
    if (!from) continue;
    const theirs = ids.get(from)!;
    out.set(s, { from, shared: new Set(evs.map((e) => e.id).filter((id) => theirs.has(id))) });
  }
  return out;
}

/** findForks over a store, recomputed only when an events file changes. */
export class ForkIndex {
  private key = "";
  private forks = new Map<string, Fork>();

  constructor(private readonly store: Store) {}

  get(): Map<string, Fork> {
    const sessions = this.store.listSessions();
    const key = sessions.map((s) => `${s}:${size(this.store.eventsFile(s))}`).join();
    if (key !== this.key) {
      this.forks = findForks(new Map(sessions.map((s) => [s, this.store.readEvents(s)])));
      this.key = key;
    }
    return this.forks;
  }
}

function size(file: string): number {
  try {
    return fs.statSync(file).size;
  } catch {
    return -1;
  }
}
"}

